def sym(h,w,p):
 p=set(p); out=[]
 # geometric reflections preserving rectangle
 transforms=[('horizontal',lambda r,c:(h-1-r,c)),('vertical',lambda r,c:(r,w-1-c)),('180',lambda r,c:(h-1-r,w-1-c))]
 if h==w: transforms += [('diagonal',lambda r,c:(c,r)),('anti-diagonal',lambda r,c:(h-1-c,w-1-r))]
 for n,f in transforms:
  if {f(r,c) for r,c in p}==p:out.append(n)
 return out
